const CACHE_KEY = 'ml_monstres_v6', EQUIPE_KEY = 'ml_equipe_v6', HISTORY_KEY = 'ml_history_v6',
    THEME_KEY = 'ml_theme', ONBOARD_KEY = 'ml_onboarded', COLLECTION_KEY = 'ml_collection_v6';
const CACHE_TTL = 3600000, MAX_HISTORY = 5, SCORE_MAX = 50;

const rarityScore = { common: 0, uncommon: 1, rare: 2, epic: 3, legendary: 4, mythic: 5, ancestral: 6, ancestor: 6 };
const rarityOrder = { common: 0, uncommon: 1, rare: 2, epic: 3, legendary: 4, mythic: 5, ancestral: 6, ancestor: 6 };

// Rôles reconnus (étendu)
const ROLE_TYPE = {
    tank: 'tank', attacker: 'attacker', support: 'support',
    curser: 'curser', controler: 'controler', monster: 'attacker'
};

let STAT_MAX = { hp: 1, attack: 1, speed: 1 };

// Table des avantages/désavantages élémentaires Monster Legends
// Fort = +30% dégâts infligés, Faible = -30% dégâts infligés
// Source : wiki officiel ML / communauté
const SYNERGIES = {
    feu: { fort: ['nature', 'métal'], faible: ['eau', 'terre'] },
    eau: { fort: ['feu', 'terre'], faible: ['foudre', 'nature'] },
    nature: { fort: ['eau', 'terre'], faible: ['feu', 'métal'] },
    terre: { fort: ['foudre', 'feu'], faible: ['eau', 'nature'] },
    foudre: { fort: ['eau', 'métal'], faible: ['terre', 'nature'] },
    métal: { fort: ['nature', 'foudre'], faible: ['feu', 'terre'] },
    ténèbres: { fort: ['lumière', 'magie'], faible: ['lumière'] },
    lumière: { fort: ['ténèbres'], faible: ['ténèbres', 'magie'] },
    magie: { fort: ['lumière', 'nature'], faible: ['ténèbres'] },
    spécial: { fort: [], faible: [] },
};
const ELEMENT_BONUS = +30;   // % de dégâts bonus si avantage
const ELEMENT_MALUS = -30;   // % de dégâts si désavantage

let monstres = {}, monstresFiltres = {}, monstresFiltresCollection = {},
    sortMode = 'alpha', currentMode = 'simple';
let maCollection = new Set();
let modeCollectionActif = false;

// ===================== THEME =====================
function toggleTheme() {
    const html = document.documentElement, isLight = html.getAttribute('data-theme') === 'light';
    const next = isLight ? 'dark' : 'light';
    html.setAttribute('data-theme', next);
    document.querySelector('.btn-theme').textContent = next === 'dark' ? '🌙' : '☀️';
    localStorage.setItem(THEME_KEY, next);
}
function initTheme() {
    const saved = localStorage.getItem(THEME_KEY) || 'dark';
    document.documentElement.setAttribute('data-theme', saved);
    document.querySelector('.btn-theme').textContent = saved === 'dark' ? '🌙' : '☀️';
}
initTheme();

// ===================== ONBOARDING =====================
let onboardStep = 0;
const onboardSteps = document.querySelectorAll('.onboarding-step');
const onboardDots = document.querySelectorAll('.onboarding-dot');
function showOnboarding() {
    if (localStorage.getItem(ONBOARD_KEY)) return;
    document.getElementById('onboardingOverlay').classList.add('open');
}
function onboardGo(step) {
    onboardSteps.forEach(s => s.classList.remove('active'));
    onboardDots.forEach(d => d.classList.remove('active'));
    onboardSteps[step].classList.add('active');
    onboardDots[step].classList.add('active');
    document.getElementById('onboardingNext').textContent = step >= onboardSteps.length - 1 ? 'Commencer !' : 'Suivant →';
}
document.getElementById('onboardingNext').addEventListener('click', () => {
    onboardStep++;
    if (onboardStep >= onboardSteps.length) {
        document.getElementById('onboardingOverlay').classList.remove('open');
        localStorage.setItem(ONBOARD_KEY, '1');
    } else onboardGo(onboardStep);
});
document.getElementById('onboardingSkip').addEventListener('click', () => {
    document.getElementById('onboardingOverlay').classList.remove('open');
    localStorage.setItem(ONBOARD_KEY, '1');
});

// ===================== STATS =====================
function statsAuNiveau(base, lvl) {
    return {
        hp: Math.round(base.hp * Math.pow(lvl / 100, 2.38)),
        attack: Math.round(base.attack * Math.pow(lvl / 100, 2.19)),
        speed: Math.round(base.speed * Math.pow(lvl / 100, 1.26))
    };
}
function getStatsEffectives(nom, niveauId) {
    return statsAuNiveau(monstres[nom].stats, parseInt(document.getElementById(niveauId).value));
}
function getElems(m) { return Array.isArray(m.element) ? m.element : [m.element]; }
function getRole1(m) {
    const r = Array.isArray(m.role) ? m.role[0] : m.role;
    return (r && ROLE_TYPE[r]) ? ROLE_TYPE[r] : (r || 'attacker');
}
function getRoles(m) {
    const rs = Array.isArray(m.role) ? m.role : [m.role];
    return rs.map(r => (r && ROLE_TYPE[r]) ? ROLE_TYPE[r] : 'attacker');
}

// ===================== CACHE =====================
function chargerCache() { return null; } // DB intégrée
function sauvegarderCache(data) { } // DB intégrée

// ===================== COLLECTION =====================
function chargerCollection() {
    try {
        const r = localStorage.getItem(COLLECTION_KEY);
        maCollection = r ? new Set(JSON.parse(r)) : new Set();
    } catch { maCollection = new Set(); }
}
function sauvegarderCollectionLS() {
    try { localStorage.setItem(COLLECTION_KEY, JSON.stringify([...maCollection])); } catch { }
}
function getSourceMonstres() {
    if (modeCollectionActif && maCollection.size >= 3) return monstresFiltresCollection;
    return monstresFiltres;
}
function mettreAJourCollectionFiltres() {
    monstresFiltresCollection = {};
    for (const n of maCollection) {
        if (monstresFiltres[n]) monstresFiltresCollection[n] = monstresFiltres[n];
    }
}

// ===================== MODAL COLLECTION =====================
function ouvrirModalCollection() {
    const modal = document.getElementById('collectionModal');
    modal.classList.add('open');
    afficherListeCollection();
}
function fermerModalCollection() {
    document.getElementById('collectionModal').classList.remove('open');
}
function afficherListeCollection() {
    const search = document.getElementById('collectionSearch').value.toLowerCase();
    const filtreEl = document.getElementById('collFiltreElement').value;
    const filtreRar = document.getElementById('collFiltreRarete').value;
    const container = document.getElementById('collectionList');
    container.innerHTML = '';

    let noms = Object.keys(monstres).filter(n => {
        const m = monstres[n];
        if (search && !n.toLowerCase().includes(search)) return false;
        if (filtreEl && !getElems(m).includes(filtreEl)) return false;
        if (filtreRar && m.rarity !== filtreRar) return false;
        return true;
    });
    noms = trierNoms(noms);

    // Possédés en premier
    const owned = noms.filter(n => maCollection.has(n));
    const notOwned = noms.filter(n => !maCollection.has(n));
    const sorted = [...owned, ...notOwned];

    document.getElementById('collectionCount').textContent =
        `${maCollection.size} / ${Object.keys(monstres).length} monstres possédés`;

    sorted.forEach(n => {
        const m = monstres[n];
        const isOwned = maCollection.has(n);
        const rarColor = getRarityColor(m.rarity);
        const elems = getElems(m).join(' / ');

        const card = document.createElement('div');
        card.className = 'coll-card' + (isOwned ? ' owned' : '');
        card.style.setProperty('--rar-color', rarColor);
        card.innerHTML = `
            <div class="coll-card-check">${isOwned ? '✓' : ''}</div>
            <div class="coll-card-name">${n}</div>
            <div class="coll-card-id">#${m.id}</div>
            <div class="coll-card-meta">
                <span class="coll-card-elem">${elems}</span>
                <span class="coll-card-rar" style="color:${rarColor}">${m.rarity}</span>
            </div>`;

        card.addEventListener('click', () => {
            const nowOwned = maCollection.has(n);
            if (nowOwned) maCollection.delete(n); else maCollection.add(n);
            card.classList.toggle('owned', !nowOwned);
            card.querySelector('.coll-card-check').textContent = !nowOwned ? '✓' : '';
            if (!nowOwned) card.style.setProperty('--rar-color', rarColor);
            sauvegarderCollectionLS();
            mettreAJourCollectionFiltres();
            majBoutonCollection();
            document.getElementById('collectionCount').textContent =
                `${maCollection.size} / ${Object.keys(monstres).length} monstres possédés`;
        });

        container.appendChild(card);
    });
}
function majBoutonCollection() {
    const btn = document.getElementById('btnCollection');
    if (modeCollectionActif) {
        btn.textContent = '👜 Ma collection (' + maCollection.size + ') ✓';
        btn.classList.add('active');
    } else {
        btn.textContent = '👜 Ma collection (' + maCollection.size + ')';
        btn.classList.remove('active');
    }
}
function toggleModeCollection() {
    modeCollectionActif = !modeCollectionActif;
    majBoutonCollection();
    mettreAJourCollectionFiltres();
    remplirSelects();
    const hint = document.getElementById('collectionHint');
    hint.style.display = modeCollectionActif ? 'block' : 'none';
}
function selectionnerTout() {
    const noms = Object.keys(monstres);
    noms.forEach(n => maCollection.add(n));
    sauvegarderCollectionLS();
    mettreAJourCollectionFiltres();
    majBoutonCollection();
    afficherListeCollection();
}
function deselectionnerTout() {
    maCollection.clear();
    sauvegarderCollectionLS();
    mettreAJourCollectionFiltres();
    majBoutonCollection();
    afficherListeCollection();
}
function importerCollection() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = e => {
        const file = e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = ev => {
            try {
                const data = JSON.parse(ev.target.result);
                if (Array.isArray(data)) {
                    // Format: liste de noms ou liste d'objets {nom:...}
                    data.forEach(item => {
                        const nom = typeof item === 'string' ? item : item.nom;
                        if (nom && monstres[nom]) maCollection.add(nom);
                    });
                }
                sauvegarderCollectionLS();
                mettreAJourCollectionFiltres();
                majBoutonCollection();
                afficherListeCollection();
            } catch { alert('Fichier JSON invalide'); }
        };
        reader.readAsText(file);
    };
    input.click();
}
function exporterCollection() {
    const data = [...maCollection];
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'ma_collection_ml.json'; a.click();
    URL.revokeObjectURL(url);
}

// ===================== ÉQUIPE =====================
function sauvegarderEquipe() {
    try {
        localStorage.setItem(EQUIPE_KEY, JSON.stringify({
            m1: getCustomSelectValue('monstre1'), n1: document.getElementById('niveau1').value,
            m2: getCustomSelectValue('monstre2'), n2: document.getElementById('niveau2').value,
            m3: getCustomSelectValue('monstre3'), n3: document.getElementById('niveau3').value
        }));
    } catch { }
}
function restaurerEquipe() {
    const params = new URLSearchParams(window.location.search);
    if (params.get('m1') && params.get('m2') && params.get('m3')) {
        let allOk = true;
        ['m1', 'm2', 'm3'].forEach((k, i) => {
            const nom = decodeURIComponent(params.get(k)), lvl = params.get('n' + (i + 1)) || '100';
            if (monstres[nom]) {
                setCustomSelect('monstre' + (i + 1), nom);
                document.getElementById('niveau' + (i + 1)).value = lvl;
            } else { allOk = false; }
        });
        if (allOk) setTimeout(calculer, 50);
        return;
    }
    try {
        const r = localStorage.getItem(EQUIPE_KEY);
        if (!r) return;
        const { m1, n1, m2, n2, m3, n3 } = JSON.parse(r);
        if (monstres[m1]) { setCustomSelect('monstre1', m1); document.getElementById('niveau1').value = n1; }
        if (monstres[m2]) { setCustomSelect('monstre2', m2); document.getElementById('niveau2').value = n2; }
        if (monstres[m3]) { setCustomSelect('monstre3', m3); document.getElementById('niveau3').value = n3; }
        if (monstres[m1] && monstres[m2] && monstres[m3]) setTimeout(calculer, 50);
    } catch { }
}

// ===================== HISTORIQUE =====================
function chargerHistorique() { try { return JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]'); } catch { return []; } }
function sauvegarderHistorique(h) { try { localStorage.setItem(HISTORY_KEY, JSON.stringify(h)); } catch { } }
function ajouterHistorique(eq, niveaux, score) {
    let h = chargerHistorique();
    const key = eq.join('|');
    h = h.filter(e => e.key !== key);
    h.unshift({ key, eq, niveaux, score: Math.round(score), date: new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) });
    if (h.length > MAX_HISTORY) h = h.slice(0, MAX_HISTORY);
    sauvegarderHistorique(h);
    afficherHistorique();
}
function afficherHistorique() {
    const h = chargerHistorique(), section = document.getElementById('historySection'), list = document.getElementById('historyList');
    if (!h.length) { section.style.display = 'none'; return; }
    section.style.display = 'block';
    list.innerHTML = '';
    h.forEach((entry, idx) => {
        const div = document.createElement('div');
        div.className = 'history-item';
        div.innerHTML = `<div class="history-monsters">${entry.eq.map((n, i) => `${n} <span style="color:var(--gold-dark);font-size:10px">Niv.${entry.niveaux[i]}</span>`).join(' · ')}</div><div class="history-score">${entry.score}/${SCORE_MAX}</div><div class="history-date">${entry.date}</div><button class="history-del" onclick="supprimerHistorique(${idx},event)">✕</button>`;
        div.addEventListener('click', () => chargerDepuisHistorique(entry));
        list.appendChild(div);
    });
}
function supprimerHistorique(idx, e) { e.stopPropagation(); let h = chargerHistorique(); h.splice(idx, 1); sauvegarderHistorique(h); afficherHistorique(); }
function chargerDepuisHistorique(entry) {
    if (monstres[entry.eq[0]]) { setCustomSelect('monstre1', entry.eq[0]); document.getElementById('niveau1').value = entry.niveaux[0]; }
    if (monstres[entry.eq[1]]) { setCustomSelect('monstre2', entry.eq[1]); document.getElementById('niveau2').value = entry.niveaux[1]; }
    if (monstres[entry.eq[2]]) { setCustomSelect('monstre3', entry.eq[2]); document.getElementById('niveau3').value = entry.niveaux[2]; }
    calculerAvecTransition();
}

// ===================== EXPORT =====================
function exporterEquipe() {
    const params = new URLSearchParams({
        m1: getCustomSelectValue('monstre1'), n1: document.getElementById('niveau1').value,
        m2: getCustomSelectValue('monstre2'), n2: document.getElementById('niveau2').value,
        m3: getCustomSelectValue('monstre3'), n3: document.getElementById('niveau3').value
    });
    const url = window.location.origin + window.location.pathname + '?' + params.toString();
    navigator.clipboard.writeText(url).then(() => {
        const btn = document.getElementById('btnExport');
        btn.textContent = '✅ Copié!';
        btn.classList.add('copied');
        setTimeout(() => { btn.textContent = '🔗 Partager'; btn.classList.remove('copied'); }, 2000);
    }).catch(() => prompt('Copie ce lien :', url));
}

// ===================== MODE =====================
function setMode(mode, btn) {
    currentMode = mode;
    document.querySelectorAll('.mode-tab').forEach(t => t.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById('modeSimple').style.display = mode === 'simple' ? 'block' : 'none';
    document.getElementById('modeCompare').style.display = mode === 'compare' ? 'block' : 'none';
    if (mode === 'compare') remplirSelectsCompare();
}

// ===================== CUSTOM SELECT =====================
let customSelects = {};

function creerCustomSelect(containerId, options, onChange) {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = '';
    container.className = 'custom-select-wrap';

    const MAX_VISIBLE = 60;
    let currentValue = options[0]?.value || '';
    let isOpen = false;

    // --- Trigger ---
    const display = document.createElement('div');
    display.className = 'cs-display';
    display.innerHTML = '<span class="cs-disp-name">—</span><span class="cs-arrow">▼</span>';

    // --- Dropdown ---
    const dropdown = document.createElement('div');
    dropdown.className = 'cs-dropdown';

    // Header: search + filters
    const dropHeader = document.createElement('div');
    dropHeader.className = 'cs-drop-header';

    const search = document.createElement('input');
    search.className = 'cs-search';
    search.placeholder = '🔍 Rechercher un monstre...';
    search.autocomplete = 'off';

    const filterRow = document.createElement('div');
    filterRow.className = 'cs-filter-row';

    // Build element list from current options
    const allElems = [...new Set(options.flatMap(o => {
        const m = monstres[o.value];
        return m ? (Array.isArray(m.element) ? m.element : [m.element]) : [];
    }))].sort();
    const RARITY_ORDER = ['common', 'uncommon', 'rare', 'epic', 'legendary', 'mythic', 'ancestral', 'ancestor'];
    const allRars = RARITY_ORDER.filter(r => options.some(o => monstres[o.value]?.rarity === r));

    const elSel = document.createElement('select');
    elSel.className = 'cs-filter-sel';
    elSel.innerHTML = '<option value="">Tous éléments</option>' + allElems.map(e => `<option value="${e}">${e}</option>`).join('');

    const rarSel = document.createElement('select');
    rarSel.className = 'cs-filter-sel';
    rarSel.innerHTML = '<option value="">Toutes raretés</option>' + allRars.map(r => `<option value="${r}">${r}</option>`).join('');

    filterRow.appendChild(elSel);
    filterRow.appendChild(rarSel);

    const counter = document.createElement('div');
    counter.className = 'cs-counter';

    dropHeader.appendChild(search);
    dropHeader.appendChild(filterRow);
    dropHeader.appendChild(counter);

    // List
    const list = document.createElement('div');
    list.className = 'cs-list';

    dropdown.appendChild(dropHeader);
    dropdown.appendChild(list);

    function getFiltered() {
        const txt = search.value.toLowerCase();
        const el = elSel.value;
        const rar = rarSel.value;
        return options.filter(o => {
            if (txt && !o.label.toLowerCase().includes(txt)) return false;
            const m = monstres[o.value];
            if (!m) return false;
            if (el) { const elems = Array.isArray(m.element) ? m.element : [m.element]; if (!elems.includes(el)) return false; }
            if (rar && m.rarity !== rar) return false;
            return true;
        });
    }

    function renderOptions() {
        const filtered = getFiltered();
        const shown = filtered.slice(0, MAX_VISIBLE);
        list.innerHTML = '';
        shown.forEach(opt => {
            const m = monstres[opt.value];
            const elems = m ? (Array.isArray(m.element) ? m.element : [m.element]) : [];
            const rarColor = getRarityColor(m?.rarity);
            const item = document.createElement('div');
            item.className = 'cs-option' + (opt.value === currentValue ? ' selected' : '');
            item.dataset.value = opt.value;
            const thumb = m ? `<img class="cs-opt-img" src="img/${m.id}.webp" onerror="this.style.display='none'" loading="lazy">` : '';
            item.innerHTML = `${thumb}<span class="cs-opt-name">${opt.label}</span><span class="cs-opt-badges"><span class="cs-opt-elem">${elems.join('/')}</span><span class="cs-opt-rar" style="color:${rarColor}">${m?.rarity || ''}</span></span>`;
            item.addEventListener('mousedown', e => {
                e.preventDefault();
                setValue(opt.value, opt.label);
                close();
                onChange(opt.value);
            });
            list.appendChild(item);
        });
        const more = filtered.length - MAX_VISIBLE;
        counter.textContent = more > 0
            ? `${MAX_VISIBLE} affichés / ${filtered.length} résultats — affinez la recherche`
            : `${filtered.length} / ${options.length} monstres`;
        const sel = list.querySelector('.selected');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    }

    function setValue(val, label) {
        currentValue = val;
        const m = monstres[val];
        const rarColor = getRarityColor(m?.rarity);
        const elems = m ? (Array.isArray(m.element) ? m.element : [m.element]) : [];
        const dispThumb = m ? `<img class="cs-disp-img" src="img/${m.id}.webp" onerror="this.style.display='none'">` : '';
        display.innerHTML = `${dispThumb}<span class="cs-disp-name">${label || val}</span><span class="cs-disp-badges"><span class="cs-disp-elem">${elems.join('/')}</span><span class="cs-disp-rar" style="color:${rarColor}">${m?.rarity || ''}</span></span><span class="cs-arrow">▼</span>`;
        display.dataset.value = val;
    }

    function open() {
        if (isOpen) return;
        isOpen = true;
        Object.values(customSelects).forEach(cs => { if (cs?.close && cs !== api) cs.close(); });
        // Positionner le dropdown en fixed sous le display
        const rect = display.getBoundingClientRect();
        const spaceBelow = window.innerHeight - rect.bottom;
        const dropH = 360; // hauteur max estimée
        dropdown.style.left = rect.left + 'px';
        dropdown.style.width = Math.max(rect.width, 280) + 'px';
        if (spaceBelow >= dropH || spaceBelow > window.innerHeight / 2) {
            dropdown.style.top = (rect.bottom + 4) + 'px';
            dropdown.style.bottom = 'auto';
        } else {
            dropdown.style.bottom = (window.innerHeight - rect.top + 4) + 'px';
            dropdown.style.top = 'auto';
        }
        container.classList.add('open');
        search.value = ''; elSel.value = ''; rarSel.value = '';
        renderOptions();
        setTimeout(() => search.focus(), 30);
    }

    function close() {
        isOpen = false;
        container.classList.remove('open');
    }

    // Navigate with arrows + Enter
    function focusItem(dir) {
        const items = [...list.querySelectorAll('.cs-option')];
        if (!items.length) return;
        const cur = list.querySelector('.cs-option.kb-focus');
        let idx = cur ? items.indexOf(cur) : -1;
        cur?.classList.remove('kb-focus');
        idx = (idx + dir + items.length) % items.length;
        items[idx].classList.add('kb-focus');
        items[idx].scrollIntoView({ block: 'nearest' });
    }

    display.addEventListener('click', () => isOpen ? close() : open());
    search.addEventListener('input', renderOptions);
    elSel.addEventListener('change', renderOptions);
    rarSel.addEventListener('change', renderOptions);
    search.addEventListener('keydown', e => {
        if (e.key === 'Escape') { close(); e.stopPropagation(); }
        if (e.key === 'ArrowDown') { e.preventDefault(); focusItem(1); }
        if (e.key === 'ArrowUp') { e.preventDefault(); focusItem(-1); }
        if (e.key === 'Enter') {
            const focused = list.querySelector('.cs-option.kb-focus') || list.querySelector('.cs-option');
            if (focused) { setValue(focused.dataset.value, focused.querySelector('.cs-opt-name').textContent); close(); onChange(focused.dataset.value); }
        }
    });
    document.addEventListener('click', e => { if (!container.contains(e.target)) close(); });
    window.addEventListener('scroll', () => { if (isOpen) close(); }, { passive: true });
    window.addEventListener('resize', () => { if (isOpen) close(); }, { passive: true });

    container.appendChild(display);
    container.appendChild(dropdown);

    if (options.length) setValue(options[0].value, options[0].label);

    const api = {
        getValue: () => currentValue,
        setValue: (v) => { const o = options.find(x => x.value === v); if (o) setValue(o.value, o.label); },
        updateOptions: (newOpts) => {
            options = newOpts;
            // Rebuild element/rarity lists
            const newElems = [...new Set(newOpts.flatMap(o => { const m = monstres[o.value]; return m ? (Array.isArray(m.element) ? m.element : [m.element]) : []; }))].sort();
            elSel.innerHTML = '<option value="">Tous éléments</option>' + newElems.map(e => `<option value="${e}">${e}</option>`).join('');
            if (isOpen) renderOptions();
            if (!newOpts.find(o => o.value === currentValue)) { if (newOpts[0]) setValue(newOpts[0].value, newOpts[0].label); }
        },
        close
    };
    return api;
}

function getRarityColor(rarity) {
    const colors = { common: '#90a4ae', uncommon: '#b1bb78', rare: '#4fc3f7', epic: '#ce93d8', legendary: '#ffd166', mythic: '#ff5252', ancestral: '#64b5f6', ancestor: '#64b5f6' };
    return colors[rarity] || 'var(--text-dim)';
}

function getCustomSelectValue(id) {
    return customSelects[id]?.getValue() || '';
}
function setCustomSelect(id, val) {
    customSelects[id]?.setValue(val);
}

function buildOptions(source) {
    return trierNoms(Object.keys(source)).map(n => ({
        value: n, label: n,
        rarity: monstres[n].rarity
    }));
}

function initCustomSelects() {
    const src = getSourceMonstres();
    const opts = buildOptions(src);
    ['monstre1', 'monstre2', 'monstre3'].forEach((id, i) => {
        const containerId = id + '_cs';
        if (!document.getElementById(containerId)) {
            const wrap = document.getElementById(id);
            if (!wrap) return;
            wrap.id = containerId;
        }
        const prev = getCustomSelectValue(id);
        customSelects[id] = creerCustomSelect(id + '_cs', [...opts], () => onMonstreChange());
        if (prev && src[prev]) customSelects[id].setValue(prev);
    });
}

function mettreAJourCustomSelects() {
    const src = getSourceMonstres();
    const opts = buildOptions(src);
    ['monstre1', 'monstre2', 'monstre3'].forEach(id => {
        if (customSelects[id]) {
            const prev = getCustomSelectValue(id);
            customSelects[id].updateOptions([...opts]);
            if (prev && src[prev]) customSelects[id].setValue(prev);
        }
    });
    verifierDoublons();
    mettreAJourCompteur();
}

// ===================== CHARGEMENT =====================
function initialiser(data) {
    monstres = {};
    data.forEach(m => {
        if (!m.nom) return;
        monstres[m.nom] = {
            id: m.id,
            role: m.role && m.role.length ? m.role : ['attacker'],
            element: m.element,
            rarity: m.rarity || 'common',
            stats: m.stats || { hp: 0, attack: 0, speed: 0 },
            skills: m.skills || [],
            books: m.books || []
        };
    });

    STAT_MAX = {
        hp: Math.max(...Object.values(monstres).map(m => m.stats.hp)),
        attack: Math.max(...Object.values(monstres).map(m => m.stats.attack)),
        speed: Math.max(...Object.values(monstres).map(m => m.stats.speed))
    };

    chargerCollection();
    monstresFiltres = { ...monstres };
    mettreAJourCollectionFiltres();
    remplirFiltreElements();
    remplirFiltreElementsCollection();
    remplirSynergieAdversaire();
    remplirNiveaux();
    initCustomSelects();
    restaurerEquipe();
    afficherHistorique();
    majBoutonCollection();
    showOnboarding();
    // calculer() est lancé uniquement quand l'utilisateur clique sur Analyser
    // Afficher/masquer le sélecteur d'élément selon le mode
    const autoModeSel = document.getElementById('autoMode');
    const autoElemSel = document.getElementById('autoElement');
    if (autoModeSel && autoElemSel) {
        autoModeSel.addEventListener('change', () => {
            autoElemSel.style.display = autoModeSel.value === 'element' ? 'inline-flex' : 'none';
        });
    }
}

// DB intégrée directement — pas besoin de fetch
initialiser(MONSTRES_DB);

// ===================== FILTRES =====================
function remplirFiltreElements() {
    const sel = document.getElementById('filtreElement');
    const oldVal = sel.value;
    while (sel.options.length > 1) sel.remove(1);
    const elements = [...new Set(Object.values(monstres).flatMap(m => getElems(m)))].sort();
    elements.forEach(el => { const o = document.createElement('option'); o.value = el; o.textContent = '🌿 ' + el; sel.appendChild(o); });
    if (oldVal) sel.value = oldVal;
}
function remplirFiltreElementsCollection() {
    const sel = document.getElementById('collFiltreElement');
    if (!sel) return;
    while (sel.options.length > 1) sel.remove(1);
    const elements = [...new Set(Object.values(monstres).flatMap(m => getElems(m)))].sort();
    elements.forEach(el => { const o = document.createElement('option'); o.value = el; o.textContent = el; sel.appendChild(o); });
}
function remplirSynergieAdversaire() {
    const sel = document.getElementById('synergieAdversaire');
    while (sel.options.length > 1) sel.remove(1);
    const elements = [...new Set(Object.values(monstres).flatMap(m => getElems(m)))].sort();
    elements.forEach(el => { const o = document.createElement('option'); o.value = el; o.textContent = el; sel.appendChild(o); });
}
function appliquerFiltres() {
    const el = document.getElementById('filtreElement').value, ra = document.getElementById('filtreRarete').value;
    monstresFiltres = {};
    for (let n in monstres) {
        const m = monstres[n];
        if (el && !getElems(m).includes(el)) continue;
        if (ra && m.rarity !== ra) continue;
        monstresFiltres[n] = m;
    }
    mettreAJourCollectionFiltres();
    remplirSelects();
    mettreAJourCompteur();
}
function resetFiltres() {
    document.getElementById('filtreElement').value = '';
    document.getElementById('filtreRarete').value = '';
    monstresFiltres = { ...monstres };
    mettreAJourCollectionFiltres();
    remplirSelects();
    mettreAJourCompteur();
}
function mettreAJourCompteur() {
    const src = getSourceMonstres();
    const n = Object.keys(src).length, total = Object.keys(monstres).length;
    const filtN = Object.keys(monstresFiltres).length;
    let txt = '';
    if (modeCollectionActif) txt = `👜 ${n} monstres (collection)`;
    else if (filtN !== total) txt = `${filtN} / ${total} monstres`;
    else txt = `${total} monstres`;
    document.getElementById('filterCounter').textContent = txt;
}

// ===================== TRI =====================
function setSortMode(mode, btn) {
    sortMode = mode;
    document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    remplirSelects();
}
function trierNoms(noms) {
    return [...noms].sort((a, b) => {
        if (sortMode === 'alpha') return a.localeCompare(b);
        if (sortMode === 'id') return (monstres[a]?.id || 0) - (monstres[b]?.id || 0);
        if (sortMode === 'rarity') return (rarityOrder[monstres[b]?.rarity] || 0) - (rarityOrder[monstres[a]?.rarity] || 0);
        if (sortMode === 'element') {
            const ea = getElems(monstres[a])[0], eb = getElems(monstres[b])[0];
            return ea.localeCompare(eb) || a.localeCompare(b);
        }
        return 0;
    });
}

// ===================== SELECTS =====================
function remplirSelects() {
    mettreAJourCustomSelects();
}
function remplirSelectsCompare() {
    const src = getSourceMonstres();
    ['cmpA1', 'cmpA2', 'cmpA3', 'cmpB1', 'cmpB2', 'cmpB3'].forEach(id => {
        const s = document.getElementById(id), old = s.value;
        s.innerHTML = '';
        trierNoms(Object.keys(src)).forEach(n => { const o = document.createElement('option'); o.value = n; o.textContent = n; s.appendChild(o); });
        if (old && src[old]) s.value = old;
    });
    ['cnivA1', 'cnivA2', 'cnivA3', 'cnivB1', 'cnivB2', 'cnivB3'].forEach(id => {
        const s = document.getElementById(id); if (s.children.length) return;
        for (let lvl = 1; lvl <= 150; lvl++) { const o = document.createElement('option'); o.value = lvl; o.textContent = 'Niv. ' + lvl; if (lvl === 100) o.selected = true; s.appendChild(o); }
    });
}
function remplirNiveaux() {
    ['niveau1', 'niveau2', 'niveau3'].forEach(id => {
        const s = document.getElementById(id); s.innerHTML = '';
        for (let lvl = 1; lvl <= 150; lvl++) { const o = document.createElement('option'); o.value = lvl; o.textContent = 'Niv. ' + lvl; if (lvl === 100) o.selected = true; s.appendChild(o); }
    });
}

// ===================== DOUBLONS =====================
function verifierDoublons() {
    const vals = [getCustomSelectValue('monstre1'), getCustomSelectValue('monstre2'), getCustomSelectValue('monstre3')];
    [1, 2, 3].forEach(i => {
        const hasDup = vals.filter(v => v === vals[i - 1]).length > 1;
        const row = document.getElementById('row' + i);
        const warn = document.getElementById('warn' + i);
        if (row) row.classList.toggle('duplicate', hasDup);
        if (warn) warn.style.display = hasDup ? 'inline' : 'none';
    });
    return vals[0] === vals[1] || vals[1] === vals[2] || vals[0] === vals[2];
}

// ===================== SYNERGIE =====================
function calculerSynergie() {
    const adv = document.getElementById('synergieAdversaire').value;
    const result = document.getElementById('synergieResult');
    if (!adv) { result.innerHTML = ''; return; }
    const eq = [getCustomSelectValue('monstre1'), getCustomSelectValue('monstre2'), getCustomSelectValue('monstre3')].filter(n => monstres[n]);
    if (!eq.length) { result.innerHTML = ''; return; }

    const syn = SYNERGIES[adv] || { fort: [], faible: [] };
    let forts = 0, faibles = 0, neutres = 0;
    let rows = '';

    eq.forEach(n => {
        const m = monstres[n];
        const elems = getElems(m);
        // Calcule le meilleur modificateur parmi les éléments du monstre
        let bestMod = 0, bestElem = '';
        elems.forEach(e => {
            if (syn.faible.includes(e) && ELEMENT_BONUS > bestMod) { bestMod = ELEMENT_BONUS; bestElem = e; }
            if (syn.fort.includes(e) && ELEMENT_MALUS < bestMod) {
                if (bestMod === 0) { bestMod = ELEMENT_MALUS; bestElem = e; }
            }
        });
        // si un élément donne avantage ET un autre désavantage → avantage gagne
        const hasStrong = elems.some(e => syn.faible.includes(e));
        const hasWeak = elems.some(e => syn.fort.includes(e));
        let cls, icon, modLabel, mod;
        if (hasStrong) {
            cls = 'syn-strong'; icon = '✅'; mod = +ELEMENT_BONUS;
            modLabel = `+${ELEMENT_BONUS}% dégâts`;
            forts++;
        } else if (hasWeak) {
            cls = 'syn-weak'; icon = '❌'; mod = ELEMENT_MALUS;
            modLabel = `${ELEMENT_MALUS}% dégâts`;
            faibles++;
        } else {
            cls = 'syn-neutral'; icon = '➖'; mod = 0;
            modLabel = 'Neutre (±0%)';
            neutres++;
        }
        const img = m.id ? `<img class="syn-thumb" src="img/${m.id}.webp" onerror="this.style.display='none'">` : '';
        rows += `<div class="syn-row ${cls}">
            ${img}
            <div class="syn-row-info">
                <span class="syn-row-name">${n}</span>
                <span class="syn-row-elem">${elems.join(' / ')}</span>
            </div>
            <span class="syn-row-mod">${icon} ${modLabel}</span>
        </div>`;
    });

    // Résumé global
    const total = eq.length;
    let summaryClass = '', summaryText = '';
    if (forts === total) {
        summaryClass = 'syn-summary-great';
        summaryText = `🔥 Toute la team est forte contre ${adv} — +${ELEMENT_BONUS}% sur tous les monstres !`;
    } else if (forts >= 2) {
        summaryClass = 'syn-summary-good';
        summaryText = `👍 ${forts}/${total} monstres ont l'avantage contre ${adv}`;
    } else if (faibles >= 2) {
        summaryClass = 'syn-summary-bad';
        summaryText = `⚠️ ${faibles}/${total} monstres sont en désavantage contre ${adv} — prudence`;
    } else if (faibles === total) {
        summaryClass = 'syn-summary-danger';
        summaryText = `💀 Toute la team est faible contre ${adv} — ${ELEMENT_MALUS}% sur tous les monstres`;
    } else {
        summaryClass = 'syn-summary-neutral';
        summaryText = `${forts > 0 ? forts + ' avantage' : ''}${neutres > 0 ? ' · ' + neutres + ' neutre' : ''}${faibles > 0 ? ' · ' + faibles + ' désavantage' : ''} contre ${adv}`;
    }

    // Quels éléments counterent ta team ?
    const teamElems = [...new Set(eq.flatMap(n => getElems(monstres[n])))];
    const counters = Object.entries(SYNERGIES)
        .filter(([el, s]) => teamElems.some(te => s.faible.includes(te)))
        .map(([el]) => el);
    const counterHTML = counters.length
        ? `<div class="syn-counters">⚠️ <b>Ta team est countertée par :</b> ${counters.join(', ')}</div>`
        : `<div class="syn-counters">✅ Aucun élément du wiki ne contre toute ta team.</div>`;

    result.innerHTML = `
        <div class="syn-summary ${summaryClass}">${summaryText}</div>
        <div class="syn-rows">${rows}</div>
        ${counterHTML}`;
}

// ===================== CHANGEMENT AUTO =====================
let debounceTimer = null;
function onMonstreChange() {
    ['monstre1', 'monstre2', 'monstre3'].forEach(id => {
        const nom = getCustomSelectValue(id);
        if (nom && monstres[nom]) { const img = new Image(); img.src = `img/${monstres[nom].id}.webp`; }
    });
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => { verifierDoublons(); sauvegarderEquipe(); calculerAvecTransition(); calculerSynergie(); }, 80);
}
function onCompareChange() { clearTimeout(debounceTimer); debounceTimer = setTimeout(() => comparerTeams(), 80); }

// ===================== TRANSITION =====================
function calculerAvecTransition() {
    const team = document.getElementById('teamVisuel');
    if (!team.children.length) { calculer(); return; }
    team.classList.add('fading'); team.classList.remove('visible');
    setTimeout(() => {
        calculer(); team.classList.remove('fading'); team.classList.add('visible');
        setTimeout(() => { team.querySelectorAll('.stat-bar-fill').forEach(b => { b.style.width = b.getAttribute('data-width') + '%'; }); }, 30);
    }, 150);
}

// ===================== SEARCH =====================
function filtrer() {
    const txt = document.getElementById('search').value.toLowerCase();
    const suggestions = document.getElementById('suggestions');
    suggestions.innerHTML = '';
    if (!txt) return;
    Object.keys(monstres).filter(n => n.toLowerCase().includes(txt)).slice(0, 6).forEach(n => {
        const div = document.createElement('div'); div.textContent = n; div.onclick = () => showDetail(n); suggestions.appendChild(div);
    });
}

// ===================== SIDEBAR =====================
function showDetail(n) {
    const m = monstres[n];
    const detailCard = document.getElementById('detailCard');
    const detailContent = document.getElementById('detailContent');
    detailCard.classList.add('open');
    const skillsHtml = m.skills && m.skills.length
        ? `<div class="skill-list"><div style="font-size:10px;letter-spacing:2px;color:var(--gold-dark);margin:10px 0 6px;font-weight:700;">COMPÉTENCES</div>${m.skills.map(s => `<div class="skill-item"><div class="skill-name">${s.name}</div><div class="skill-desc">${s.desc || ''}</div></div>`).join('')}</div>`
        : '';
    const booksHtml = m.books && m.books.length
        ? `<div style="font-size:10px;color:var(--text-dim);margin-top:6px">📚 ${m.books.join(', ')}</div>` : '';
    detailContent.innerHTML = `
        <h2>${n}</h2>
        <img src="img/${m.id}.webp" loading="lazy" onerror="this.src='img/default.webp'">
        <p>⚔️ ${Array.isArray(m.role) ? m.role.join(' / ') : m.role}</p>
        <p>🌿 ${getElems(m).join(' · ')}</p>
        <p class="rarity ${m.rarity}">💎 ${m.rarity}</p>
        <p style="color:var(--text-dim);font-size:11px">#${m.id}</p>
        ${booksHtml}${skillsHtml}`;
}
function closeDetail() { document.getElementById('detailCard').classList.remove('open'); }

// ===================== MODAL PLEIN ÉCRAN =====================
function ouvrirModal(nom, niveauId) {
    const m = monstres[nom], s = getStatsEffectives(nom, niveauId);
    const pctHp = Math.min(100, Math.round(s.hp / STAT_MAX.hp * 100));
    const pctAtk = Math.min(100, Math.round(s.attack / STAT_MAX.attack * 100));
    const pctSpd = Math.min(100, Math.round(s.speed / STAT_MAX.speed * 100));
    const elems = getElems(m);
    const skillsHtml = m.skills && m.skills.length
        ? m.skills.map(sk => `<div class="skill-item"><div class="skill-name">${sk.name}</div><div class="skill-desc">${sk.desc || ''}</div></div>`).join('')
        : '<div style="color:var(--text-dim);font-size:12px;">Aucune compétence renseignée</div>';
    const booksHtml = m.books && m.books.length
        ? `<div style="font-size:11px;color:var(--text-dim);margin:8px 0;text-align:center">📚 ${m.books.join(', ')}</div>` : '';
    document.getElementById('modalContent').innerHTML = `
        <img class="modal-img" src="img/${m.id}.webp" onerror="this.src='img/default.webp'">
        <div class="modal-name">${nom}</div>
        <div style="text-align:center;font-size:11px;color:var(--text-dim);margin-bottom:4px">#${m.id}</div>
        ${booksHtml}
        <div class="modal-tags">
            <span class="tag">${Array.isArray(m.role) ? m.role.join(' / ') : m.role}</span>
            ${elems.map(el => `<span class="tag">${el}</span>`).join('')}
            <span class="tag rarity ${m.rarity}">${m.rarity}</span>
        </div>
        <div class="modal-stats">
            <div class="modal-stat-row"><span class="modal-stat-label">❤️</span><div class="modal-stat-bar-bg"><div class="modal-stat-bar-fill" data-w="${pctHp}" style="width:0%;background:linear-gradient(90deg,#c0392b,#e74c3c);"></div></div><span class="modal-stat-val">${s.hp.toLocaleString()}</span></div>
            <div class="modal-stat-row"><span class="modal-stat-label">⚔️</span><div class="modal-stat-bar-bg"><div class="modal-stat-bar-fill" data-w="${pctAtk}" style="width:0%;background:linear-gradient(90deg,#c17f24,#f0a500);"></div></div><span class="modal-stat-val">${s.attack.toLocaleString()}</span></div>
            <div class="modal-stat-row"><span class="modal-stat-label">💨</span><div class="modal-stat-bar-bg"><div class="modal-stat-bar-fill" data-w="${pctSpd}" style="width:0%;background:linear-gradient(90deg,#1a6fa8,#3498db);"></div></div><span class="modal-stat-val">${s.speed.toLocaleString()}</span></div>
        </div>
        <div class="modal-skills-title">Compétences</div>
        ${skillsHtml}`;
    document.getElementById('modalOverlay').classList.add('open');
    setTimeout(() => { document.querySelectorAll('.modal-stat-bar-fill').forEach(b => { b.style.width = b.getAttribute('data-w') + '%'; }); }, 50);
}
function fermerModal(e) {
    if (!e || e.target === document.getElementById('modalOverlay')) document.getElementById('modalOverlay').classList.remove('open');
}


// ===================== RECOMMANDATION RUNES =====================
// Runes disponibles : Force (ATK), Vie (HP), Vitesse (SPD), Vitesse d'équipe (TSPD)
// Source : role.txt — recommandations officielles par rôle
function recommanderRunes(m, s) {
    const roles = getRoles(m);
    const r1 = getRole1(m);

    // Détecter si attacker pur ou perçant (vitesse déjà très haute)
    const isHighSpeed = s.speed / STAT_MAX.speed > 0.72;
    const isHighAtk = s.attack / STAT_MAX.attack > 0.72;

    let runes = [], note = '';

    if (r1 === 'tank') {
        // Tank : 2 Vie + 1 Vitesse/Vit.équipe (survie max, agir vite)
        runes = ['❤️ Vie', '❤️ Vie', '💨 Vitesse'];
        note = "Absorbe les dégâts pour protéger l'équipe — priorité survie.";
    } else if (r1 === 'support') {
        // Support Taunt/Megataunt → 2 Vie + 1 Vit.
        // Support Heal/Buff → 2 Vitesse d'équipe + 1 Vie
        if (isHighSpeed) {
            runes = ["💨 Vit. d'équipe", "💨 Vit. d'équipe", '❤️ Vie'];
            note = "Vitesse d'équipe pour booster tes alliés et agir en premier.";
        } else {
            runes = ['❤️ Vie', '❤️ Vie', '💨 Vitesse'];
            note = 'Si ce support a Taunt/Megataunt, il doit encaisser — privilégie la survie.';
        }
    } else if (r1 === 'attacker') {
        if (isHighSpeed) {
            // Attacker perçant (déjà rapide)
            runes = ['⚔️ Force', '💨 Vitesse', '💨 Vitesse'];
            note = "Attacker perçant/rapide — augmente encore la vitesse pour frapper avant l'esquive adverse.";
        } else {
            // Attacker brut
            runes = ['⚔️ Force', '⚔️ Force', '💨 Vitesse'];
            note = 'Dégâts bruts : 2 Force pour dévaster, 1 Vitesse pour agir. Si un allié a des runes Vit.équipe, tu peux passer à 3 Force.';
        }
    } else if (r1 === 'curser') {
        // Denier/Attacker — tortures + dégâts
        runes = ['⚔️ Force', '💨 Vitesse', '💨 Vitesse'];
        note = "Applique ses tortures et dégâts avant l'adversaire — vitesse critique, force pour amplifier les dégâts par torture.";
    } else if (r1 === 'controler') {
        // Denier — nier avant d'être nié
        runes = ['💨 Vitesse', '💨 Vitesse', "💨 Vit. d'équipe"];
        note = "Le Denier doit agir en PREMIER — 3 runes de vitesse pour étourdir/geler l'adversaire avant qu'il ne joue.";
    } else {
        // monster / fallback attacker
        runes = ['⚔️ Force', '⚔️ Force', '💨 Vitesse'];
        note = 'Attacker générique — priorité aux dégâts.';
    }

    return { runes, note };
}

// ===================== SCORE =====================
function scoreIndividuel(m, s) {
    const role = getRole1(m);
    // Tank : survie max, une touche de vitesse pour agir
    if (role === 'tank') return (s.hp / STAT_MAX.hp) * 3.0 + (s.speed / STAT_MAX.speed) * 0.7 + (s.attack / STAT_MAX.attack) * 0.3;
    // Attacker : ATK d'abord, vitesse importante, HP secondaire
    if (role === 'attacker') return (s.attack / STAT_MAX.attack) * 3.0 + (s.speed / STAT_MAX.speed) * 1.0 + (s.hp / STAT_MAX.hp) * 0.3;
    // Support : vitesse critique (agir avant l'adversaire), puis survie
    if (role === 'support') return (s.speed / STAT_MAX.speed) * 3.0 + (s.hp / STAT_MAX.hp) * 0.7 + (s.attack / STAT_MAX.attack) * 0.2;
    // Curser : vitesse + ATK (applique les tortures vite et fort)
    if (role === 'curser') return (s.speed / STAT_MAX.speed) * 2.5 + (s.attack / STAT_MAX.attack) * 2.0 + (s.hp / STAT_MAX.hp) * 0.2;
    // Controler : vitesse primordiale (nier avant d'être nié), HP pour survivre
    if (role === 'controler') return (s.speed / STAT_MAX.speed) * 3.0 + (s.hp / STAT_MAX.hp) * 0.8 + (s.attack / STAT_MAX.attack) * 0.5;
    // monster (= attacker générique)
    return (s.attack / STAT_MAX.attack) * 2.5 + (s.speed / STAT_MAX.speed) * 1.0 + (s.hp / STAT_MAX.hp) * 0.3;
}

// Labels lisibles pour les rôles
const ROLE_LABELS = {
    tank: '🛡️ Tank',
    attacker: '⚔️ Attacker',
    support: '✨ Support',
    curser: '☠️ Curser (Denier/Attacker)',
    controler: '🚫 Controler (Denier)',
    monster: '⚔️ Attacker'
};

function calculScore(eq, niveauxIds) {
    let roles = {}, elements = [], exp = [], conseils = [], score = 0;
    eq.forEach((n, i) => {
        const m = monstres[n], s = getStatsEffectives(n, niveauxIds[i]);
        getRoles(m).forEach(r => { roles[r] = (roles[r] || 0) + 1; });
        getElems(m).forEach(el => elements.push(el));
        score += rarityScore[m.rarity] || 0;
        score += Math.min(4, scoreIndividuel(m, s) * (4 / 4.3));
    });

    const t = roles.tank || 0;
    const a = roles.attacker || 0;
    const su = roles.support || 0;
    const cu = roles.curser || 0;
    const co = roles.controler || 0;
    const c = cu + co;

    // --- Composition (max 9 pts) ---
    if (t === 1 && a === 1 && su === 1) { score += 9; exp.push('🛡️⚔️✨ Compo idéale : Tank · Attacker · Support'); }
    else if (t === 1 && a === 1 && c >= 1) { score += 9; exp.push('🛡️⚔️🌀 Compo idéale : Tank · Attacker · ' + (cu > 0 ? 'Curser' : 'Controler')); }
    else if (a === 1 && su === 1 && c >= 1) { score += 8; exp.push('⚔️✨🌀 Attacker · Support · ' + (cu > 0 ? 'Curser' : 'Controler')); }
    else if (t === 1 && su === 1 && c >= 1) { score += 7; exp.push('🛡️✨🌀 Tank · Support · ' + (cu > 0 ? 'Curser' : 'Controler')); }
    else if (a === 2 && su === 1) { score += 7; exp.push('⚔️⚔️✨ Double Attacker · Support'); }
    else if (a === 2 && c >= 1) { score += 7; exp.push('⚔️⚔️🌀 Double Attacker · ' + (cu > 0 ? 'Curser' : 'Controler')); }
    else if (t === 1 && a === 2) { score += 6; exp.push('🛡️⚔️⚔️ Tank · Double Attacker'); }
    else if (t === 1 && c >= 2) { score += 6; exp.push('🛡️🌀🌀 Tank · Double Control'); }
    else if (a === 3) { score += 5; exp.push('⚔️⚔️⚔️ Triple Attacker (fragile)'); }
    else if (t === 1 && su === 2) { score += 4; exp.push('🛡️✨✨ Tank · Double Support (passif)'); }
    else if (c >= 2 && a >= 1) { score += 6; exp.push('🌀🌀⚔️ Double Control · Attacker'); }
    else { score += 3; conseils.push('Compo non optimale — essaie Tank+Attacker+Support ou Tank+Attacker+Curser'); }

    // --- Éléments (max 3 pts) ---
    const uniq = new Set(elements);
    score += uniq.size;
    if (uniq.size === 3) exp.push('🌈 Diversité élémentaire parfaite');
    else if (uniq.size === 2) conseils.push('Ajoute un 3ème élément pour maximiser la diversité');
    else conseils.push('Diversité élémentaire faible — tous les monstres ont le même élément');
    if (uniq.size < 2) score -= 2;

    // --- Rareté ---
    let avg = 0; eq.forEach(n => { avg += rarityScore[monstres[n].rarity] || 0; }); avg /= 3;
    if (avg >= 5.5) exp.push('💎 Rareté : Tier Dieu');
    else if (avg >= 4.5) exp.push('💎 Rareté : Exceptionnelle');
    else if (avg >= 3.5) exp.push('💎 Très forte rareté');
    else if (avg >= 2.5) exp.push('✨ Bonne rareté');
    else exp.push('⚠️ Rareté faible');

    // --- Books synergy (max 8 pts) ---
    const bookCounts = {};
    eq.forEach(n => { (monstres[n].books || []).forEach(b => { bookCounts[b] = (bookCounts[b] || 0) + 1; }); });
    let bookBonus = 0;
    const books3 = [], books2 = [];
    Object.entries(bookCounts).forEach(([b, cnt]) => {
        if (cnt === 3) { bookBonus += 4; books3.push(b); }
        else if (cnt === 2) { bookBonus += 1.5; books2.push(b); }
    });
    bookBonus = Math.min(8, bookBonus);
    score += bookBonus;
    if (books3.length) exp.push(`📚 Bonus Book complet (+4/book) : ${books3.join(', ')}`);
    else if (books2.length) exp.push(`📚 Bonus Book partiel (+1.5/book) : ${books2.slice(0, 3).join(', ')}`);
    else conseils.push('Aucun book partagé — aligner 2-3 monstres du même book donne des bonus de stats passifs');

    score = Math.min(score, SCORE_MAX);
    return { score, exp, conseils };
}

// ===================== AFFICHER ÉQUIPE =====================
function afficherEquipe(eq, niveauxIds, containerId) {
    const container = document.getElementById(containerId); container.innerHTML = '';
    eq.forEach((n, i) => {
        const m = monstres[n];
        if (!m) return;
        const s = getStatsEffectives(n, niveauxIds[i]);
        const niveau = document.getElementById(niveauxIds[i]).value;
        const pctHp = Math.min(100, Math.round(s.hp / STAT_MAX.hp * 100));
        const pctAtk = Math.min(100, Math.round(s.attack / STAT_MAX.attack * 100));
        const pctSpd = Math.min(100, Math.round(s.speed / STAT_MAX.speed * 100));
        const div = document.createElement('div'); div.className = 'card';
        div.onclick = () => ouvrirModal(n, niveauxIds[i]);
        div.innerHTML = `
            <div class="card-img-wrap"><img src="img/${m.id}.webp" loading="lazy" onerror="this.src='img/default.webp'"></div>
            <div class="card-body">
                <div class="card-name">${n}</div>
                <div class="card-id">#${m.id}</div>
                <div class="card-tags">
                    <span class="tag">${Array.isArray(m.role) ? m.role.join('/') : m.role}</span>
                    ${getElems(m).map(el => `<span class="tag">${el}</span>`).join('')}
                    <span class="tag rarity ${m.rarity}">${m.rarity}</span>
                </div>
                <div class="stat-level">NIV. ${niveau}</div>
                <div class="card-divider"></div>
                <div class="card-stats">
                    <div class="stat-row"><span class="stat-label">❤️</span><div class="stat-bar-bg"><div class="stat-bar-fill" data-width="${pctHp}" style="width:0%;background:linear-gradient(90deg,#c0392b,#e74c3c)"></div></div><span class="stat-val">${s.hp.toLocaleString()}</span></div>
                    <div class="stat-row"><span class="stat-label">⚔️</span><div class="stat-bar-bg"><div class="stat-bar-fill" data-width="${pctAtk}" style="width:0%;background:linear-gradient(90deg,#c17f24,#f0a500)"></div></div><span class="stat-val">${s.attack.toLocaleString()}</span></div>
                    <div class="stat-row"><span class="stat-label">💨</span><div class="stat-bar-bg"><div class="stat-bar-fill" data-width="${pctSpd}" style="width:0%;background:linear-gradient(90deg,#1a6fa8,#3498db)"></div></div><span class="stat-val">${s.speed.toLocaleString()}</span></div>
                </div>
            </div>`;
        container.appendChild(div);
    });
    setTimeout(() => { container.querySelectorAll('.stat-bar-fill').forEach(b => { b.style.width = b.getAttribute('data-width') + '%'; }); }, 30);
}

function buildResultHTML(eq, niveauxIds, hasDup) {
    const { score, exp, conseils } = calculScore(eq, niveauxIds);
    const appreciation = score >= 43 ? '🔥 EXCELLENTE' : score >= 28 ? '👍 Bonne' : '❌ Faible';
    let statsLines = '', runesLines = '';
    eq.forEach((n, i) => {
        const m = monstres[n];
        if (!m) return;
        const s = getStatsEffectives(n, niveauxIds[i]);
        const ss = scoreIndividuel(m, s);
        const tier = ss >= 2.5 ? '🔥 Excellent' : ss >= 1.5 ? '✅ Bon' : ss >= 0.7 ? '⚠️ Moyen' : '❌ Faible';
        const roleLabel = ROLE_LABELS[getRole1(m)] || getRole1(m);
        statsLines += `<span class="result-line"><b>${n}</b> · ${roleLabel} · ${tier}</span>`;
        const { runes, note } = recommanderRunes(m, s);
        runesLines += `<div class="rune-block"><div class="rune-name">${n}</div><div class="rune-set">${runes.map(r => `<span class="rune-tag">${r}</span>`).join('')}</div><div class="rune-note">${note}</div></div>`;
    });
    const dupWarn = hasDup ? `<div class="result-section"><span class="result-line" style="color:#ff8080">⚠️ Monstres en doublon !</span></div>` : '';
    return {
        html: `<div class="score-display">${Math.round(score)} / ${SCORE_MAX}</div><div class="score-label">Score — ${appreciation}</div>${dupWarn}<div class="card-divider"></div><div class="result-section"><div class="result-section-title">Analyse</div>${exp.map(e => `<span class="result-line">${e}</span>`).join('')}</div><div class="result-section"><div class="result-section-title">Stats</div>${statsLines}</div><div class="result-section"><div class="result-section-title">💍 Runes recommandées</div>${runesLines}</div>${conseils.length ? `<div class="result-section"><div class="result-section-title">Conseils</div>${conseils.map(c => `<span class="result-line">👉 ${c}</span>`).join('')}</div>` : ''}`,
        score
    };
}

// ===================== CALCULER =====================
function calculer() {
    const hasDup = verifierDoublons();
    const eq = [getCustomSelectValue('monstre1'), getCustomSelectValue('monstre2'), getCustomSelectValue('monstre3')];
    const niveauxIds = ['niveau1', 'niveau2', 'niveau3'];
    if (!eq[0] || !eq[1] || !eq[2]) return;
    afficherEquipe(eq, niveauxIds, 'teamVisuel');
    const { html, score } = buildResultHTML(eq, niveauxIds, hasDup);
    document.getElementById('resultat').innerHTML = html;
    if (!hasDup) { const niveaux = niveauxIds.map(id => document.getElementById(id).value); ajouterHistorique(eq, niveaux, score); }
}

// ===================== COMPARER =====================
function comparerTeams() {
    const eqA = [document.getElementById('cmpA1').value, document.getElementById('cmpA2').value, document.getElementById('cmpA3').value];
    const eqB = [document.getElementById('cmpB1').value, document.getElementById('cmpB2').value, document.getElementById('cmpB3').value];
    const nivA = ['cnivA1', 'cnivA2', 'cnivA3'], nivB = ['cnivB1', 'cnivB2', 'cnivB3'];
    afficherEquipe(eqA, nivA, 'teamVisuelA');
    afficherEquipe(eqB, nivB, 'teamVisuelB');
    const { html: hA, score: sA } = buildResultHTML(eqA, nivA, false);
    const { html: hB, score: sB } = buildResultHTML(eqB, nivB, false);
    document.getElementById('resultatA').innerHTML = hA;
    document.getElementById('resultatB').innerHTML = hB;
    document.getElementById('compareResults').classList.add('visible');
    const winner = document.getElementById('compareWinner');
    winner.style.display = 'block';
    if (sA > sB) winner.innerHTML = `🏆 Team A gagne ! (${Math.round(sA)} vs ${Math.round(sB)})`;
    else if (sB > sA) winner.innerHTML = `🏆 Team B gagne ! (${Math.round(sB)} vs ${Math.round(sA)})`;
    else winner.innerHTML = `🤝 Égalité parfaite ! (${Math.round(sA)} / ${SCORE_MAX})`;
    setTimeout(() => {
        ['teamVisuelA', 'teamVisuelB'].forEach(id => {
            document.getElementById(id).querySelectorAll('.stat-bar-fill').forEach(b => { b.style.width = b.getAttribute('data-width') + '%'; });
        });
    }, 30);
}

// ===================== WEB WORKER OPTIMISÉ =====================
// Le worker utilise un pré-filtre par score individuel pour réduire l'espace de recherche
const WORKER_SCRIPT = `
self.onmessage = function(e) {
    const { monstresData, rarityScore, SCORE_MAX, mode, advElement } = e.data;
    const vals = Object.values(monstresData);
    if (vals.length < 3) { self.postMessage([]); return; }

    const STAT_MAX = {
        hp: Math.max(...vals.map(m => m.stats.hp)),
        attack: Math.max(...vals.map(m => m.stats.attack)),
        speed: Math.max(...vals.map(m => m.stats.speed))
    };

    const ROLE_MAP = { tank:'tank', attacker:'attacker', support:'support', curser:'curser', controler:'controler', monster:'attacker' };

    function getRole1(m) {
        const r = Array.isArray(m.role) ? m.role[0] : m.role;
        return (r && ROLE_MAP[r]) ? ROLE_MAP[r] : 'attacker';
    }
    function getRoles(m) {
        const rs = Array.isArray(m.role) ? m.role : [m.role];
        return rs.map(r => (r && ROLE_MAP[r]) ? ROLE_MAP[r] : 'attacker');
    }
    function s2l(b, l) {
        return {
            hp: Math.round(b.hp * Math.pow(l / 100, 2.38)),
            attack: Math.round(b.attack * Math.pow(l / 100, 2.19)),
            speed: Math.round(b.speed * Math.pow(l / 100, 1.26))
        };
    }
    // Synergies élémentaires (reprise dans le worker)
    const W_SYNERGIES = {
        feu:      { faible: ['nature','métal'] },
        eau:      { faible: ['feu','terre'] },
        nature:   { faible: ['eau','terre'] },
        terre:    { faible: ['foudre','feu'] },
        foudre:   { faible: ['eau','métal'] },
        métal:    { faible: ['nature','foudre'] },
        ténèbres: { faible: ['lumière','magie'] },
        lumière:  { faible: ['ténèbres'] },
        magie:    { faible: ['lumière','nature'] },
        spécial:  { faible: [] },
    };

    function indivScore(m, s) {
        const role = getRole1(m);
        // Mode vitesse : tout le monde doit être rapide
        if (mode === 'speed') {
            return (s.speed / STAT_MAX.speed) * 3.5 + (s.attack / STAT_MAX.attack) * 0.5 + (s.hp / STAT_MAX.hp) * 0.2;
        }
        // Mode DPS : ATK avant tout
        if (mode === 'dps') {
            return (s.attack / STAT_MAX.attack) * 3.5 + (s.speed / STAT_MAX.speed) * 1.0 + (s.hp / STAT_MAX.hp) * 0.2;
        }
        // Mode survie : HP avant tout
        if (mode === 'tank') {
            return (s.hp / STAT_MAX.hp) * 3.5 + (s.speed / STAT_MAX.speed) * 0.5 + (s.attack / STAT_MAX.attack) * 0.3;
        }
        // Modes balanced + element : score par rôle standard
        if (role === 'tank')      return (s.hp / STAT_MAX.hp) * 3.0 + (s.speed / STAT_MAX.speed) * 0.7 + (s.attack / STAT_MAX.attack) * 0.3;
        if (role === 'attacker')  return (s.attack / STAT_MAX.attack) * 3.0 + (s.speed / STAT_MAX.speed) * 1.0 + (s.hp / STAT_MAX.hp) * 0.3;
        if (role === 'support')   return (s.speed / STAT_MAX.speed) * 3.0 + (s.hp / STAT_MAX.hp) * 0.7 + (s.attack / STAT_MAX.attack) * 0.2;
        if (role === 'curser')    return (s.speed / STAT_MAX.speed) * 2.5 + (s.attack / STAT_MAX.attack) * 2.0 + (s.hp / STAT_MAX.hp) * 0.2;
        if (role === 'controler') return (s.speed / STAT_MAX.speed) * 3.0 + (s.hp / STAT_MAX.hp) * 0.8 + (s.attack / STAT_MAX.attack) * 0.5;
        return (s.attack / STAT_MAX.attack) * 2.5 + (s.speed / STAT_MAX.speed) * 1.0 + (s.hp / STAT_MAX.hp) * 0.3;
    }

    function sc(eq) {
        let roles = {}, elements = [], score = 0;
        eq.forEach(n => {
            const m = monstresData[n], s = s2l(m.stats, 100);
            getRoles(m).forEach(r => { roles[r] = (roles[r] || 0) + 1; });
            const els = Array.isArray(m.element) ? m.element : [m.element];
            elements.push(...els);
            score += rarityScore[m.rarity] || 0;
            score += Math.min(4, indivScore(m, s) * (4 / 4.3));
        });
        const t  = roles.tank      || 0;
        const a  = roles.attacker  || 0;
        const su = roles.support   || 0;
        const cu = roles.curser    || 0;
        const co = roles.controler || 0;
        const c  = cu + co;
        if      (t===1 && a===1 && su===1) score += 9;
        else if (t===1 && a===1 && c>=1)   score += 9;
        else if (a===1 && su===1 && c>=1)  score += 8;
        else if (t===1 && su===1 && c>=1)  score += 7;
        else if (a===2 && su===1)          score += 7;
        else if (a===2 && c>=1)            score += 7;
        else if (t===1 && a===2)           score += 6;
        else if (t===1 && c>=2)            score += 6;
        else if (c>=2 && a>=1)             score += 6;
        else if (a===3)                    score += 5;
        else if (t===1 && su===2)          score += 4;
        else                               score += 3;
        const uniq = new Set(elements);
        score += uniq.size;
        if (uniq.size < 2) score -= 2;
        // Books synergy
        const bookCounts = {};
        eq.forEach(n => { (monstresData[n].books || []).forEach(b => { bookCounts[b] = (bookCounts[b] || 0) + 1; }); });
        let bookBonus = 0;
        Object.values(bookCounts).forEach(cnt => {
            if (cnt === 3) bookBonus += 4;
            else if (cnt === 2) bookBonus += 1.5;
        });
        score += Math.min(8, bookBonus);

        // ── Bonus spécifique au mode ──
        if (mode === 'speed') {
            // Bonus si la team est globalement rapide (moyenne SPD élevée)
            const avgSpd = eq.reduce((acc, n) => acc + monstresData[n].stats.speed, 0) / eq.length;
            score += Math.min(5, (avgSpd / STAT_MAX.speed) * 6);
            // Malus si trop peu de Deniers/Controlers (la vitesse sert à nier)
            if ((roles.controler || 0) + (roles.curser || 0) === 0) score -= 2;
        }

        if (mode === 'dps') {
            // Bonus si la team a beaucoup d'Attackers
            const atkBonus = Math.min(4, (roles.attacker || 0) * 1.5 + (roles.curser || 0));
            score += atkBonus;
            // Bonus ATK moyenne
            const avgAtk = eq.reduce((acc, n) => acc + monstresData[n].stats.attack, 0) / eq.length;
            score += Math.min(4, (avgAtk / STAT_MAX.attack) * 5);
        }

        if (mode === 'tank') {
            // Bonus si au moins 1 Tank
            if ((roles.tank || 0) >= 1) score += 4;
            // Bonus HP moyen élevé
            const avgHp = eq.reduce((acc, n) => acc + monstresData[n].stats.hp, 0) / eq.length;
            score += Math.min(4, (avgHp / STAT_MAX.hp) * 5);
            // Bonus Support pour healer/protect
            if ((roles.support || 0) >= 1) score += 2;
        }

        if (mode === 'element' && advElement) {
            // Bonus fort si les éléments du monstre battent l'adversaire
            const advSyn = W_SYNERGIES[advElement] || { faible: [] };
            eq.forEach(n => {
                const els = Array.isArray(monstresData[n].element) ? monstresData[n].element : [monstresData[n].element];
                if (els.some(e => advSyn.faible.includes(e))) score += 4; // avantage élémentaire = gros bonus
                else score -= 1; // pas d'avantage = malus léger
            });
        }

        return Math.min(score, SCORE_MAX);
    }

    const noms = Object.keys(monstresData);
    
    // Heuristique : pré-trier par score individuel et garder top N
    // Réduire drastiquement l'espace de recherche
    const MAX_CANDIDATES = Math.min(noms.length, 50);
    const scored = noms.map(n => {
        const m = monstresData[n];
        const s = s2l(m.stats, 100);
        return { n, s: indivScore(m, s) + (rarityScore[m.rarity] || 0) * 0.5 };
    }).sort((a, b) => b.s - a.s);
    
    // Toujours garder des représentants de chaque rôle (tank, support, etc.)
    const byRole = {};
    noms.forEach(n => {
        const role = getRole1(monstresData[n]);
        if (!byRole[role]) byRole[role] = [];
        byRole[role].push(n);
    });
    
    const candidateSet = new Set(scored.slice(0, MAX_CANDIDATES).map(x => x.n));
    // Ajouter les meilleurs de chaque rôle
    Object.values(byRole).forEach(arr => arr.slice(0, 10).forEach(n => candidateSet.add(n)));
    const candidates = [...candidateSet];

    let best = [], bs = -Infinity;
    // Seuil d'arrêt précoce : score max réalistement atteignable dans la DB (~43)
    const MAX_SCORE = 42;

    outer: for (let i = 0; i < candidates.length; i++) {
        for (let j = i + 1; j < candidates.length; j++) {
            for (let k = j + 1; k < candidates.length; k++) {
                const eq = [candidates[i], candidates[j], candidates[k]];
                const s = sc(eq);
                if (s > bs) { bs = s; best = eq; }
                if (bs >= MAX_SCORE) break outer;
            }
        }
    }
    self.postMessage(best);
};
`;

function lancerMeilleureTeam() {
    const btn = document.getElementById('btnAuto'), spinner = document.getElementById('spinnerWrap');
    const src = getSourceMonstres();
    const nbFiltres = Object.keys(src).length;
    if (nbFiltres < 3) {
        document.getElementById('resultat').innerHTML = `<div class="score-display" style="color:#ff8080">⚠️ ${modeCollectionActif ? 'Collection' : 'Filtres'} trop restrictif${modeCollectionActif ? 'e' : 's'}</div><div class="score-label">Il faut au moins 3 monstres</div><div class="result-section"><span class="result-line">${nbFiltres} monstre(s) disponible(s).</span></div>`;
        return;
    }
    btn.disabled = true; spinner.classList.add('visible');
    const blob = new Blob([WORKER_SCRIPT], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));
    const workerTimeout = setTimeout(() => {
        worker.terminate();
        btn.disabled = false;
        spinner.classList.remove('visible');
        document.getElementById('resultat').innerHTML = `<div class="score-display" style="color:#ff8080">⏱️ Calcul trop long</div><div class="score-label">Interrompu après 20 secondes</div><div class="result-section"><span class="result-line">Réduis la liste avec les filtres ou la collection.</span></div>`;
    }, 20000);
    const autoMode = document.getElementById('autoMode')?.value || 'balanced';
    const autoElem = document.getElementById('autoElement')?.value || '';
    worker.postMessage({ monstresData: src, rarityScore, SCORE_MAX, mode: autoMode, advElement: autoElem });
    worker.onmessage = function (e) {
        clearTimeout(workerTimeout);
        const best = e.data;
        if (!best || best.length < 3) { btn.disabled = false; spinner.classList.remove('visible'); worker.terminate(); return; }
        setCustomSelect('monstre1', best[0]);
        setCustomSelect('monstre2', best[1]);
        setCustomSelect('monstre3', best[2]);
        sauvegarderEquipe(); calculerAvecTransition();
        btn.disabled = false; spinner.classList.remove('visible'); worker.terminate();
    };
    worker.onerror = function (err) {
        clearTimeout(workerTimeout);
        worker.terminate();
        btn.disabled = false; spinner.classList.remove('visible');
        console.error('Worker error:', err);
    };
}

// ===================== RACCOURCIS CLAVIER =====================
document.addEventListener('keydown', e => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT' || e.target.tagName === 'TEXTAREA') return;
    if (e.key === 'Enter') { if (currentMode === 'simple') calculer(); else comparerTeams(); }
    if (e.key === 'r' || e.key === 'R') resetFiltres();
    if (e.key === 'Escape') {
        fermerModal();
        closeDetail();
        fermerModalCollection();
        document.getElementById('onboardingOverlay').classList.remove('open');
    }
});

